insert into faqs (id, question, answer, display_order) values
  (1, 'How do I secure my appointment?', 'To lock in your slot, a ₱500 downpayment is required within 12 hours of booking. ₱400 will be deducted from your total bill, while ₱100 covers the reservation fee.', 1),
  (2, 'What happens if I don''t send the screenshot of my payment?', 'Once you have paid, you must send Clawholics your confirmation page or email confirmation to officially validate the booking. If this is not sent, your appointment may be removed from the schedule.', 2),
  (3, 'Can I get my downpayment back if I cancel?', 'Yes, but only if you cancel at least 3 days before your scheduled appointment. If you cancel later than that, the downpayment is non-refundable.', 3),
  (4, 'How do I reschedule my appointment?', 'Check your confirmation email from Clawholics. Click the "Reschedule" link provided. Please remember that rescheduling must be done at least 3 days before your original date.', 4),
  (5, 'What if I''m running late?', 'We offer a small grace period with the following fees:
